    /\ rw_cells rsegs m (bv_unsigned sp + -424) [C4 (Z_to_bv 64 0); CB 3 (K_jk3 K)]
    /\ rw_cells rsegs m (bv_unsigned sp + -417) [CB 12 (K_jk12 K)]
